import { existsSync, readFileSync } from "node:fs";
import openapiTS, { astToString } from "openapi-typescript";
import { bundlePath } from "./lib.mjs";

export const GENERATED_HEADER =
  "// GENERATED by scripts/contract-types.mjs from contracts/dist/openapi.yaml — DO NOT EDIT BY HAND.\n" +
  "// Regenerate with: npm run contract:types\n\n";

/** Generates the full content of generated/api.d.ts from the bundle. */
export async function generateTypes() {
  if (!existsSync(bundlePath)) {
    throw new Error(`${bundlePath} does not exist. Run npm run contract:bundle first.`);
  }
  const schema = readFileSync(bundlePath, "utf8");
  const ast = await openapiTS(schema, { alphabetize: true, exportType: true });
  const body = astToString(ast).replace(/\r\n/g, "\n");
  return GENERATED_HEADER + body;
}
